/* ─── Boxes ─── */
.card { padding: var(--s5); box-shadow: inset 0 0 0 1px var(--rule); }
.card-hover:hover { box-shadow: inset 0 0 0 1px var(--foreground); }
.banner { display: flex; align-items: flex-start; gap: var(--s4); padding: var(--s3) var(--s4); box-shadow: inset calc(3px * var(--dir, 1)) 0 0 var(--foreground); background: var(--wash); font-size: var(--text-sm); }
.banner > :first-child { flex: 1; min-width: 0; overflow-wrap: anywhere; }
.banner-accent { box-shadow: inset calc(3px * var(--dir, 1)) 0 0 var(--accent); }
.banner-warning { box-shadow: inset calc(3px * var(--dir, 1)) 0 0 var(--warning); }
.banner-danger { box-shadow: inset calc(3px * var(--dir, 1)) 0 0 var(--danger); }
.banner-warning strong { color: var(--warning); }
.banner-danger strong { color: var(--danger); }

/* Card parts. The legacy .card/.card-hover (06-boxes.css) draws the border. */
.card-header { display: grid; gap: var(--s1); margin-bottom: var(--s4); }
.card-title { overflow-wrap: anywhere; font-weight: 500; font-size: var(--text-lg); }
.card-description { overflow-wrap: anywhere; color: var(--muted); font-size: var(--text-sm); }
.card-content { display: grid; gap: var(--s3); }
.card-footer { display: flex; flex-wrap: wrap; gap: var(--s3); align-items: center; margin-top: var(--s5); }
a.card, button.card { display: block; text-align: start; text-decoration: none; color: inherit; width: 100%; }

